@Test
void addBeyondIntMaxIsRejectedAndKeepsStock() {
    inv.add("BOLT-M6", Integer.MAX_VALUE - 1);
    assertThrows(ArithmeticException.class, () -> inv.add("BOLT-M6", 2));
    assertEquals(Integer.MAX_VALUE - 1, inv.stockOf("BOLT-M6"));
}

